<?php foreach(range(997,1022) as $id){ $r=storage_path("app/public/sites/$id"); if(!is_file("$r/index.html")) continue; $h=file_get_contents("$r/index.html"); $w=DB::table("websites")->where("id",$id)->first(["workspace_id","status","subdomain"]); echo "$id ws=".$w->workspace_id." ".$w->status." menublock=".(int)(bool)preg_match("/data-block=\"menu\"/",$h)." menudir=".(int)is_dir("$r/menu")." pages=".implode(",",array_map("basename",array_filter(glob("$r/*"),"is_dir")))." homepage=".(DB::table("pages")->where("website_id",$id)->where("slug","home")->value("id")??"-").PHP_EOL; } foreach([477,504,507] as $id){ $p=DB::table("pages")->where("website_id",$id)->first(); echo "$id page ".$p->id." ".$p->slug." ".$p->status." ".substr((string)$p->sections_json,0,200).PHP_EOL; $w=DB::table("websites")->where("id",$id)->first(["workspace_id","status","subdomain"]); echo "   ws=".$w->workspace_id." ".$w->status." ".$w->subdomain.PHP_EOL; }
